/* Starts sequence SEQ of bank BANK on the animation at g_hero +
   0x2080: SEQ in slot 0, the next one (clamped to the bank's last) in
   slot 1, both slots on BANK, time 0x54 reset, then update_moby_animation_state. */
void HeroStartSequenceInBank(int bank, int seq) {
    AnimState *obj = *(AnimState **)&((Hero *)g_hero)->moby;
    int last;

    obj->seq[0] = seq;
    obj->seq[1] = seq + 1;
    last = obj->model->banks[bank]->count - 1;
    if (last < obj->seq[1]) {
        obj->seq[1] = last;
    }
    obj->bank[0] = bank;
    obj->bank[1] = bank;
    obj->f54 = 0.0f;
    update_moby_animation_state(obj);
}
/* Queues sequence SEQ of bank BANK (g_hero + 0xAB0 / 0xAB4) when BANK
   is valid and SEQ is below the count of the current animation's bank.
   The base pointer is a local inside the test, as retail forms it only
   there. */
void hero_queue_sequence(int bank, int seq) {
    if (bank >= 0) {
        Hero *base = (Hero *)g_hero;
        AnimState *obj = *(AnimState **)&base->moby;

        if (seq < obj->model->banks[obj->bank[1]]->count) {
            base->anim_loop_frame = bank;
            base->queued_anim_frame = seq;
        }
    }
}

