/* Adds B rounds to weapon A's ammo (weapon_ammo_counts[a]), clamped to the weapon's capacity (item_price_table[a].max):
   returns the overflow that did not fit, 0 when it all fit or the weapon has no ammo limit. */
int add_ammo(int a, int b) {
    int *p = &weapon_ammo_counts[a];
    unsigned short *q = (unsigned short *)((char *)item_price_table + a * 0x18);
    int v = *p + b;
    unsigned short t = q[7];
    *p = v;
    if (t != 0) {
        t = q[7];
        v = v - t;
        if (v > 0) {
            *p = t;
            return v;
        }
    }
    return 0;
}
/* the weapon's ammo (the current weapon for -1), or 1 when it has no ammo limit */
int get_ammo(int id) {
    AmmoInfo *e;
    if (id == -1)
        id = g_hero_equipped_item_id;
    e = &item_price_table[id];
    if (e->max == 0)
        return 1;
    return weapon_ammo_counts[id];
}

/* Records a target: POS at g_hero + 0x1640, ARG at +0x1650 and T at
   +0x164C, and unless the state (+0x2084) is already 0x65-0x67, enters
   state 0x65 (HeroEnterMoveState). The copy goes to the symbol's address
   and the base is named after it, which gives retail's base derived back
   from the copy's address; the stores are in reverse. */
void request_hero_target_pose(float *pos, int arg, float t) {
    struct Hero *base;
    int state;

    qcopy(g_hero + 0x1640, pos);
    base = (struct Hero *)g_hero;
    state = base->state.current;
    base->unk1650 = arg;
    base->target_pose.f[3] = t;
    if (state < 0x65 || state > 0x67) {
        HeroEnterMoveState(HERO_STATE_APPROACH_TARGET_POSE, 1);
    }
}

/* 1 when the word at 0x1414D4 is 101 or 102, 2 when it is 103, else 0 */
int get_hero_target_pose_status(void) {
    switch (hero_current_state) {
        case 101:
        case 102:
            return 1;
        case 103:
            return 2;
    }
    return 0;
}
